import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const barrierPhysicalScenarios={'barrier-physical-1':'a2-p18-r2c2','barrier-physical-2':'a2-p18-r2c3'} as const;
export type BarrierPhysicalScenario=keyof typeof barrierPhysicalScenarios;
export function isBarrierPhysicalScenario(name:string):name is BarrierPhysicalScenario{return Object.hasOwn(barrierPhysicalScenarios,name);}
export function makeBarrierPhysicalScenario(name:BarrierPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;mode?:'magic'|'warrior'|'multiple'|'prohibited'}={}){
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string],mode=options.mode??'magic';assignCharacter(s,a,mode==='multiple'?'凍気のアイエル':mode==='prohibited'?'吟遊詩人のレスター':'侍大将のシン');assignCharacter(s,b,'黒騎士ガーウィン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,b);s.players[b]!.permanent!.magic_level=20+(options.level??5)-stats.magic_level;s.players[b]!.permanent!.spirit=20+6-stats.spirit;
 const attack=takeCard(s,a,mode==='warrior'?'踏み込み／弓':mode==='multiple'?'氷矢':mode==='prohibited'?'呪歌':'炎舞'),card=takeCard(s,b,barrierPhysicalScenarios[name]),spare=takeCard(s,b,card==='a2-p18-r2c2'?'a2-p18-r2c3':'a2-p18-r2c2'),prayer=takeCard(s,b,'必勝の祈り'),fate=takeCard(s,c,'命運凶変');trimHand(s,a,attack);trimHand(s,b,card,spare,prayer);trimHand(s,c,fate);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`BARRIER_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('BARRIER_FIXTURE_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('BARRIER_FIXTURE_IDS');}
 for(const p of players)act(p.id,{type:'PASS_SETUP'});act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});act(a,{type:'ATTACK',cardInstanceId:attack,targetIds:mode==='multiple'?[b,c]:[b],dedicated:mode==='multiple'||mode==='prohibited'});for(let n=0;n<300;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('BARRIER_FIXTURE_WINDOW');
}
